DATA=''
SHA='f71c3a61b4897c01bf75b4055003ebd43007f79ebf35a2b34acb8a374d9e89d2'
# Enter only the live owned controller's retained mount view; stop helper remains outside its cgroup.
import base64,hashlib,json,subprocess
raw=base64.b64decode(DATA)
assert hashlib.sha256(raw).hexdigest()==SHA
unit='sst-q7b-g5-sharedvram-v3-70188b8e50fd.service'
r=subprocess.run(['systemctl','show',unit]+['--property='+x for x in ('MainPID','ControlGroup','ActiveState')],text=True,capture_output=True,timeout=20)
v=dict(x.split('=',1)for x in r.stdout.splitlines()if'='in x)
assert v['MainPID']=='1259750'and v['ActiveState']=='active'and v['ControlGroup'].endswith('/'+unit)
source='SOURCE_SHA256='+repr(SHA)+'\n'+raw.decode()
r=subprocess.run(['nsenter','--target','1259750','--mount','--','/usr/bin/python3','-'],input=source,text=True,capture_output=True,timeout=95)
print(r.stdout,end='');print(r.stderr,end='',file=__import__('sys').stderr);raise SystemExit(r.returncode)
